mapper.select:
select * from (SELECT T1.ENTRUST_ID entrustId ,T1.ENTRUST_STATUS entrustStatus, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T4.ORDER_FINISH_AMT, 0 ),0,0, nvl( T4.ORDER_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_NUM, 1 )), 4 ) ELSE ROUND( decode(nvl( T4.ORDER_FINISH_AMT, 0 ),0,0, nvl( T4.ORDER_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_AMT, 1 )), 4 ) END AS implementPercent, CASE
WHEN T2.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T4.ENT_FINISH_AMT, 0 ),0 ,0 , nvl( T4.ENT_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_NUM, 1 )), 4 ) ELSE ROUND( decode(nvl( T4.ENT_FINISH_AMT, 0 ),0,0, nvl( T4.ENT_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_AMT, 1 )), 4 ) END AS dealPercent, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( nvl( T4.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T4.ORDER_FINISH_AMT, 0 ), 4 ) END AS finishAmt, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( nvl( T1.ENTRUST_NUM, 0 ) - nvl( T4.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T1.ENTRUST_AMT, 0 ) - nvl( T4.ORDER_FINISH_AMT, 0 ), 4 ) END AS avaNum, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( nvl( T4.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T4.ENT_FINISH_AMT, 0 ), 4 ) END AS finishDealAmt, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( nvl( T1.ENTRUST_NUM, 0 ) - nvl( T4.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T1.ENTRUST_AMT, 0 ) - nvl( T4.ENT_FINISH_AMT, 0 ), 4 ) END AS avaDealAmt, nvl(detail.PORTFOLIO_ID,T5.PORTFOLIO_ID) portfolioId, nvl(detail.PORTFOLIO_NAME,T5.PORTFOLIO_NAME) portfolioName, T1.FINPROD_ID finprodId ,T7.FINPROD_MARKET_ID ,CASE WHEN T1.PS IN ('03','04') THEN T1.FINPROD_ID ELSE T7.FINPROD_ABBR END AS finprodAbbr ,T1.FINPROD_TYPE2 finprodType2 ,T1.TRADE_MARKET tradeMarket ,T1.TRADE_PLAT ,T1.PS ,T2.SEC_ACCT_ID ,SSAI.SEC_ACCT_NAME ,T2.DEAL_CUR_ACCT as dealCurAcct ,c1.acctName as dealCurAcctName ,T1.PRICE_MODEL priceModel ,T2.DEAL_MODE as declaType ,CASE WHEN T1.PS IN (#{PS_T68}, #{PS_T69}, #{PS_03}, #{PS_04}) THEN T1.PRICE * 100 ELSE T1.PRICE END price /* ,T1.ENTRUST_AMT*NVL(T1.PRICE,1) ENTRUST_AMT*/ ,T1.ENTRUST_AMT entrustAmt ,T1.ENTRUST_NUM entrustNum ,T1.VDATE ,T1.MDATE ,T2.FULL_PRICE as fprice ,T2.MATURE_YIELD * 100 as yield ,T2.CAL_MODE as calMode ,T2.COUNTER_SEAT counterSeat ,T2.COUNTER_CON_NO counterConNo ,T1.ENTRUST_TYPE ,fpt.TYPE_8 paAssetType ,case when T1.ENTRUST_TYPE in ('09','12','13','14','16') then T7.FINPROD_MARKET_ID when T1.ENTRUST_TYPE in (#{PS_10}, #{PS_11}, #{PS_12}) then T7.FINPROD_MARKET_ID when T1.STOCK_ID IS NOT NULL THEN T1.STOCK_ID ELSE T7.FINPROD_MARKET_ID END finprodMarketId /*,T7.FINPROD_MARKET_ID finprodMarketId*/ ,T1.COUNTER_ID counterId ,T2.TARGET_TYPE ,T2.TRADER ,T2.COUNTER_ORG ,T1.COUNTER_TRADER ,T2.ASSET_TYPE assetType ,T1.CREATE_TIME ,T1.ENTRUST_DATE ,T1.INV_AIM ,T1.BUSINESS_MODEL businessModel ,T1.STOCK_ID ,T2.EXP_CON_NUM ,CASE WHEN T1.PS IN (#{PS_T68}, #{PS_T69}) THEN T1.PRICE * 100 END discountRate ,CASE WHEN T1.PS IN (#{PS_T68}, #{PS_T69}) THEN T1.ENTRUST_AMT/100 END standardBondVolume FROM ETR_ENTRUST T1 INNER JOIN ETR_ENTRUST_ADD T2 ON T2.ENTRUST_ID = T1.ENTRUST_ID and (T2.ASSET_TYPE1 != 'H01' or T2.ASSET_TYPE1 is null) LEFT JOIN ETR_FINISH_STATUS T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID AND T1.ENTRUST_ID = T4.TRADE_ID LEFT JOIN PTL_PORTFOLIO T5 ON T5.PORTFOLIO_ID = T1.PORTFOLIO_ID
LEFT JOIN ( SELECT EED.ENTRUST_ID, listagg ( EED.PORTFOLIO_ID, ',' ) within GROUP ( ORDER BY EED.PORTFOLIO_ID ) AS PORTFOLIO_ID , listagg ( FP.PORTFOLIO_NAME, ',' ) within GROUP ( ORDER BY FP.PORTFOLIO_NAME ) AS PORTFOLIO_NAME FROM ETR_ENTRUST_DETAIL EED left join PTL_PORTFOLIO FP on EED.PORTFOLIO_ID = FP.PORTFOLIO_ID GROUP BY EED.ENTRUST_ID ) detail ON T1.ENTRUST_ID = detail.ENTRUST_ID
INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T6.PORTFOLIO_ID = T5.PORTFOLIO_ID
AND T6.USER_ID = #{userId}
LEFT JOIN FIN_PRODUCT T7 ON T7.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T7.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON T2.SEC_ACCT_ID = SSAI.SEC_ACCT_ID
left join (select distinct ACCT_NO acctNo1, BUSI_ACCT_NO busiAcctNo1, CCY ccy, ACCT_NAME acctName from STL_CAPACCT_INFO) c1 on T2.DEAL_CUR_ACCT = c1.acctNo1 and nvl(T1.CCY, 'CNY') = c1.ccy where T1.TRADE_MARKET in ('03','04') AND T2.ASSET_TYPE NOT IN ('F17') AND T1.CREATE_USER=#{userId}
AND T1.ENTRUST_DATE = to_date(#{sysDate},'yyyy-MM-dd')
AND T1.ENTRUST_ID LIKE CONCAT('%', CONCAT(#{entrustId}, '%'))
#{item}
AND T1.ENTRUST_DATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.ENTRUST_DATE <=to_date(#{endDate},'yyyy-MM-dd')
AND T1.INV_MANAGER_ID =#{invManagerId}
AND T1.FINPROD_ID =#{finprodMarketId}
#{item}
union all SELECT T1.ENTRUST_ID entrustId ,T1.ENTRUST_STATUS entrustStatus, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T4.ORDER_FINISH_AMT, 0 ),0,0, nvl( T4.ORDER_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_NUM, 1 )), 4 ) ELSE ROUND( decode(nvl( T4.ORDER_FINISH_AMT, 0 ),0,0, nvl( T4.ORDER_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_AMT, 1 )), 4 ) END AS implementPercent, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T4.ENT_FINISH_AMT, 0 ),0,0, nvl( T4.ENT_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_NUM, 1 )), 4 ) ELSE ROUND( decode(nvl( T4.ENT_FINISH_AMT, 0 ),0,0, nvl( T4.ENT_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_AMT, 1 )), 4 ) END AS dealPercent, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( nvl( T4.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T4.ORDER_FINISH_AMT, 0 ), 4 ) END AS finishAmt, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( nvl( T1.ENTRUST_NUM, 0 ) - nvl( T4.ORDER_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T1.ENTRUST_NUM, 0 ) - nvl( T4.ORDER_FINISH_AMT, 0 ), 4 ) END AS avaNum, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( nvl( T4.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T4.ENT_FINISH_AMT, 0 ), 4 ) END AS finishDealAmt, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( nvl( T1.ENTRUST_NUM, 0 ) - nvl( T4.ENT_FINISH_AMT, 0 ), 4 ) ELSE ROUND( nvl( T1.ENTRUST_NUM, 0 ) - nvl( T4.ENT_FINISH_AMT, 0 ), 4 ) END AS avaDealAmt, nvl(detail.PORTFOLIO_ID,T5.PORTFOLIO_ID) portfolioId, nvl(detail.PORTFOLIO_NAME,T5.PORTFOLIO_NAME) portfolioName, T1.FINPROD_ID finprodId ,T7.FINPROD_MARKET_ID ,CASE WHEN T1.PS IN ('03','04') THEN T1.FINPROD_ID ELSE T7.FINPROD_ABBR END AS finprodAbbr ,T1.FINPROD_TYPE2 finprodType2 ,T1.TRADE_MARKET tradeMarket ,T1.TRADE_PLAT ,T1.PS ,T2.SEC_ACCT_ID ,SSAI.SEC_ACCT_NAME ,T2.DEAL_CUR_ACCT ,c1.acctName as dealCurAcctName ,T1.PRICE_MODEL priceModel ,T2.DEAL_MODE as declaType ,CASE WHEN T1.PS IN (#{PS_T68}, #{PS_T69}, #{PS_03}, #{PS_04}) THEN T1.PRICE * 100 ELSE T1.PRICE END price /* ,T1.ENTRUST_AMT*NVL(T1.PRICE,1) ENTRUST_AMT*/ ,T1.ENTRUST_AMT entrustAmt ,T1.ENTRUST_NUM entrustNum ,T1.VDATE ,T1.MDATE ,T2.FULL_PRICE as fprice ,T2.MATURE_YIELD * 100 as yield ,T2.CAL_MODE as calMode ,T2.COUNTER_SEAT counterSeat ,T2.COUNTER_CON_NO counterConNo ,T1.ENTRUST_TYPE ,fpt.TYPE_8 paAssetType ,case when T1.ENTRUST_TYPE in ('09','12','13','14','16') then T7.FINPROD_MARKET_ID when T1.ENTRUST_TYPE in (#{PS_10}, #{PS_11}, #{PS_12}) then T7.FINPROD_MARKET_ID when T1.STOCK_ID IS NOT NULL THEN T1.STOCK_ID ELSE T7.FINPROD_MARKET_ID END finprodMarketId /*,T7.FINPROD_MARKET_ID finprodMarketId*/ ,T1.COUNTER_ID counterId ,T2.TARGET_TYPE ,T2.TRADER ,T2.COUNTER_ORG ,T1.COUNTER_TRADER ,T2.ASSET_TYPE assetType ,T1.CREATE_TIME ,T1.ENTRUST_DATE ,T1.INV_AIM ,T1.BUSINESS_MODEL businessModel ,T1.STOCK_ID ,T2.EXP_CON_NUM ,CASE WHEN T1.PS IN (#{PS_T68}, #{PS_T69}) THEN T1.PRICE * 100 END discountRate ,CASE WHEN T1.PS IN (#{PS_T68}, #{PS_T69}) THEN T1.ENTRUST_AMT/100 END standardBondVolume FROM WFL_ETR_ENTRUST T1 INNER JOIN WFL_ETR_ENTRUST_ADD T2 ON T2.ENTRUST_ID = T1.ENTRUST_ID and (T2.ASSET_TYPE1 != 'H01' or T2.ASSET_TYPE1 is null) LEFT JOIN ETR_FINISH_STATUS T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID AND T1.ENTRUST_ID = T4.TRADE_ID LEFT JOIN PTL_PORTFOLIO T5 ON T5.PORTFOLIO_ID = T1.PORTFOLIO_ID
LEFT JOIN ( SELECT EED.ENTRUST_ID, listagg ( EED.PORTFOLIO_ID, ',' ) within GROUP ( ORDER BY EED.PORTFOLIO_ID ) AS PORTFOLIO_ID , listagg ( FP.PORTFOLIO_NAME, ',' ) within GROUP ( ORDER BY FP.PORTFOLIO_NAME ) AS PORTFOLIO_NAME FROM WFL_ETR_ENTRUST_DETAIL EED left join PTL_PORTFOLIO FP on EED.PORTFOLIO_ID = FP.PORTFOLIO_ID GROUP BY EED.ENTRUST_ID ) detail ON T1.ENTRUST_ID = detail.ENTRUST_ID
INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T6.PORTFOLIO_ID = T5.PORTFOLIO_ID
AND T6.USER_ID = #{userId}
LEFT JOIN FIN_PRODUCT T7 ON T7.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T7.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON T2.SEC_ACCT_ID = SSAI.SEC_ACCT_ID
left join (select distinct ACCT_NO acctNo1, BUSI_ACCT_NO busiAcctNo1, CCY ccy, ACCT_NAME acctName from STL_CAPACCT_INFO) c1 on T2.DEAL_CUR_ACCT = c1.acctNo1 and nvl(T1.CCY, 'CNY') = c1.ccy where T1.TRADE_MARKET in ('03','04') AND T2.ASSET_TYPE NOT IN ('F17') AND T1.CREATE_USER=#{userId}
AND T1.ENTRUST_DATE = to_date(#{sysDate},'yyyy-MM-dd')
AND T1.ENTRUST_ID LIKE CONCAT('%', CONCAT(#{entrustId}, '%'))
#{item}
AND T1.ENTRUST_DATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.ENTRUST_DATE <=to_date(#{endDate},'yyyy-MM-dd')
AND T1.INV_MANAGER_ID =#{invManagerId}
AND T1.FINPROD_ID =#{finprodMarketId}
) T1 left join SYS_DATADICT_LIST sdl1 on T1.entrustStatus=sdl1.ITEM_CODE and sdl1.DICT_CODE='ENTRUST_STATUS' left join SYS_DATADICT_LIST sdl2 on T1.PS=sdl2.ITEM_CODE and sdl2.DICT_CODE='PS' left join SYS_DATADICT_LIST sdl3 on T1.tradeMarket=sdl3.ITEM_CODE and sdl3.DICT_CODE='TRADE_PLACE' left join SYS_DATADICT_LIST sdl4 on T1.priceModel=sdl4.ITEM_CODE and sdl4.DICT_CODE='PRICE_MODEL' LEFT JOIN SYS_DATADICT_LIST sdl5 ON T1.DECLATYPE=sdl5.ITEM_CODE AND sdl5.DICT_CODE='DECLA_TYPE' LEFT JOIN SYS_DATADICT_LIST sdl6 ON T1.FINPRODTYPE2=sdl6.ITEM_CODE AND sdl6.DICT_CODE='FINPROD_TYPE_TG' where 1=1
#{tradePlat,jdbcType=VARCHAR}
#{portfolioId,jdbcType=VARCHAR}
AND T1.PS = #{ps,jdbcType=VARCHAR}
AND T1.FINPROD_MARKET_ID = #{secId,jdbcType=VARCHAR}
AND T1.FINPRODMARKETID in
#{item, jdbcType=VARCHAR}
AND T1.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
#{item}
order by ${sort} ${direction}
ORDER BY T1.CREATE_TIME DESC

SELECT TEMP.PORTFOLIO_ID AS portfolioId, PP.PORTFOLIO_NAME AS portfolioName, TEMP.SEC_ACCT_ID AS secAcctId, SSAI.SEC_ACCT_NAME AS secAcctName, TEMP.FINPROD_ID AS finprodId, FP.FINPROD_MARKET_ID AS finprodMarketId, FP.FINPROD_ABBR as finprodName, CASE WHEN instr(FP.FINPROD_MARKET_ID,'.') > 0 THEN SUBSTR(FP.FINPROD_MARKET_ID,1,instr(FP.FINPROD_MARKET_ID,'.',-1,1)-1) ELSE FP.FINPROD_MARKET_ID END AS secId, FP.FINPROD_ABBR AS secName, TEMP.AMOUNT AS positionsNum, invaim.INV_AIM as invAim, invaim.BUSINESS_MODEL as businessModel, FP.FINPROD_TYPE2 AS finprodType2, FP.TRADE_MARKET AS tradeMarket, c1.acctNo1 AS acctNo, c1.acctName as dealCurAcctName FROM ( SELECT A.CDATE AS CDATE, A.PORTFOLIO_ID AS PORTFOLIO_ID , A.SEC_ACCT_ID AS SEC_ACCT_ID , A.FINPROD_ID AS FINPROD_ID, SUM(A.AMOUNT) AMOUNT, SUM(A.ptlPositionsNum) ptlPositionsNum from( SELECT PSP.CDATE AS CDATE, PSP.PORTFOLIO_ID AS PORTFOLIO_ID , PSP.SEC_ACCT_ID AS SEC_ACCT_ID , PSP.FINPROD_ID AS FINPROD_ID, SUM(PSP.AMOUNT) AMOUNT, 0 as ptlPositionsNum FROM PTL_SEC_POSITION_RULE PSP INNER JOIN PTL_PORTFOLIO PP ON PSP.PORTFOLIO_ID = PP.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE PSP.DATE_TYPE =0 AND PSP.HODING_TYPE=#{A_001} AND PSP.CDATE = #{sysDate} GROUP BY PSP.CDATE, PSP.PORTFOLIO_ID , PSP.SEC_ACCT_ID, PSP.FINPROD_ID union SELECT ETRPSP.CDATE AS CDATE, ETRPSP.PORTFOLIO_ID AS PORTFOLIO_ID , ETRPSP.SEC_ACCT_ID AS SEC_ACCT_ID , ETRPSP.FINPROD_ID, 0 AS AMOUNT, SUM(ETRPSP.AMOUNT) as ptlPositionsNum FROM ETR_SEC_POSITION_RULE ETRPSP INNER JOIN PTL_PORTFOLIO PP ON ETRPSP.PORTFOLIO_ID = PP.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE ETRPSP.DATE_TYPE =0 AND ETRPSP.CDATE = #{sysDate} GROUP BY ETRPSP.CDATE, ETRPSP.PORTFOLIO_ID , ETRPSP.SEC_ACCT_ID, ETRPSP.FINPROD_ID) A GROUP BY A.CDATE, A.PORTFOLIO_ID , A.SEC_ACCT_ID, A.FINPROD_ID )TEMP LEFT JOIN FIN_PRODUCT FP ON TEMP.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE FPT ON FPT.FINPROD_ID = FP.FINPROD_ID LEFT JOIN PTL_PORTFOLIO PP ON TEMP.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON TEMP.SEC_ACCT_ID = SSAI.SEC_ACCT_ID left join (select distinct ACCT_NO acctNo1, BUSI_ACCT_NO busiAcctNo1, CCY ccy, ACCT_NAME acctName from STL_CAPACCT_INFO) c1 on SSAI.TRD_ACCT_ID = c1.acctNo1
left join ( select FINPROD_ID, PORTFOLIO_ID, listagg(INV_AIM, ',') WITHIN GROUP (ORDER BY PORTFOLIO_ID, FINPROD_ID) as INV_AIM, listagg(BUSINESS_MODEL, ',') WITHIN GROUP (ORDER BY PORTFOLIO_ID, FINPROD_ID) as BUSINESS_MODEL from ( SELECT FINPROD_ID, PORTFOLIO_ID, INV_AIM,BUSINESS_MODEL FROM ( select a.INV_AIM ,a.BUSINESS_MODEL, a.TRADE_DATE ,a.FINPROD_ID,b.PORTFOLIO_ID, ROW_NUMBER () over( PARTITION BY a.TRADE_ID ORDER BY a.TRADE_DATE DESC ) rn from TRD_PRODUCT_DEAL a LEFT JOIN TRD_PRODUCT_DEAL_ADD b ON a.TRADE_ID =b.TRADE_ID WHERE 1=1
AND b.PORTFOLIO_ID in
#{item}
AND a.TRADE_DATE <= #{sysDate} ) WHERE rn = 1 UNION SELECT a.FINPROD_ID, b.PORTFOLIO_ID, a.INV_AIM,a.BUSINESS_MODEL from TRD_PRODUCT_TEMP_DEAL a LEFT JOIN TRD_PRODUCT_TEMP_DEAL_ADD b ON a.TRADE_ID =b.TRADE_ID WHERE 1=1
AND b.PORTFOLIO_ID in
#{item}
AND a.TRADE_DATE = #{sysDate} ) GROUP BY FINPROD_ID, PORTFOLIO_ID ) invaim on invaim.FINPROD_ID=TEMP.FINPROD_ID and invaim.PORTFOLIO_ID=TEMP.PORTFOLIO_ID WHERE FP.TRADE_MARKET IN (#{TRADE_PLACE_03}, #{TRADE_PLACE_04})
AND FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01,jdbcType=VARCHAR} AND FPT.TYPE_6=#{TYPE_6,jdbcType=VARCHAR} AND FP.TRADE_MARKET=#{TRADE_PLACE_03}
AND ( (FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01,jdbcType=VARCHAR} AND FPT.TYPE_6=#{TYPE_6,jdbcType=VARCHAR}) or (FP.FINPROD_TYPE2 in (#{FINPROD_TYPE_TG_F06}, #{FINPROD_TYPE_TG_F10})))
AND ( (FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01,jdbcType=VARCHAR} AND FPT.TYPE_6=#{TYPE_6,jdbcType=VARCHAR}) or (FP.FINPROD_TYPE2 in (#{FINPROD_TYPE_TG_F06}, #{FINPROD_TYPE_TG_F10})))
AND FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01,jdbcType=VARCHAR}
#{portfolioId,jdbcType=VARCHAR}
AND FP.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{finprodName}, '%'))
AND FP.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
AND TEMP.SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
AND FP.FINPROD_MARKET_ID = #{secId,jdbcType=VARCHAR}
AND FP.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND FP.FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR}
AND (FP.FINPROD_MARKET_ID in
#{item, jdbcType=VARCHAR}
) OR (FP.FINPROD_ID in
#{item, jdbcType=VARCHAR} )

SELECT A.VDATE startDate, A.MDATE endDate, ( SELECT MIN(C.VDATE) FROM FIN_CASH_PLAN C WHERE C.CASH_ID = B.CASH_ID ) firstPayDate, A.ISSUE_PRICE issuePrice, A.COUPON_SPECIES bondsType, E.BASIS basis, F.INT_TYPE intRateType, G.PAY_CYCLE yearIntRate, G.CALC_RULE calMethod, H.EXERCISE_DATE nextExeDate, H.EXERCISE_PRICE nextExercisePrice FROM FIN_PRODUCT A LEFT JOIN FIN_CASH_INFO B ON A.FINPROD_ID = B.FINPROD_ID AND B.FINPROD_TYPE = #{finprodType} AND B.CASH_TYPE_1 = #{cashType1} LEFT JOIN FIN_PRODUCT_TYPE D ON D.FINPROD_ID = A.FINPROD_ID
LEFT JOIN FIN_CASH_INFO T1 ON A.FINPROD_ID = T1.FINPROD_ID AND T1.CASH_TYPE_2 = 'C02' AND T1.FINPROD_TYPE = '01' left join (select FINPROD_ID, max(eff_date) as EFF_DATE from FIN_CASH_CALC_RULE group by FINPROD_ID) T2 on T2.FINPROD_ID = A.FINPROD_ID LEFT JOIN FIN_CASH_CALC_RULE E ON E.FINPROD_ID = A.FINPROD_ID and E.EFF_DATE = T2.EFF_DATE AND E.CASH_ID = T1.CASH_ID AND E.FINPROD_TYPE2 = 'F01' and E.IS_INITIAL = 'Y'
LEFT JOIN FIN_RATE_INFO F ON F.CASH_ID = B.CASH_ID AND F.FINPROD_TYPE2 = #{finprodType2} LEFT JOIN FIN_CASH_PAY_RULE G ON G.CASH_ID = B.CASH_ID AND G.FINPROD_TYPE2 = #{finprodType2} LEFT JOIN ( SELECT * FROM FIN_EXERCISE_PLAN WHERE EXERCISE_DATE IN ( SELECT MIN(EXERCISE_DATE) FROM FIN_EXERCISE_PLAN WHERE FINPROD_ID = #{finprodId} AND FINPROD_TYPE2 = #{finprodType2} AND EXERCISE_DATE >= #{sysDate} ) AND FINPROD_ID = #{finprodId} AND FINPROD_TYPE2 = #{finprodType2} AND EXERCISE_TYPE = #{EXEC_MODE02} AND EXERCISE_TYPE = #{EXEC_MODE01} and rownum = 1 ) H ON 1=1 WHERE A.FINPROD_ID = #{finprodId}

SELECT
       100 - NVL(sum(fcp.PRIN_AMT), 0)
FROM
     FIN_CASH_PLAN fcp
     inner join FIN_CASH_INFO fci
     on fcp.CASH_ID = fci.CASH_ID
WHERE
    fcp.FINPROD_ID = #{finprodId}

    AND fcp.MDATE < #{settleDate}
    and fci.CASH_TYPE_1 = #{cashType1}


where
    FINPROD_ID = #{finprodId}
    and FINPROD_TYPE2 = #{finprodType}
order by EFF_DATE

SELECT t.COUNTER_ORG code FROM ( SELECT DISTINCT etr_add.COUNTER_ORG FROM ETR_ENTRUST_ADD etr_add INNER JOIN ETR_ENTRUST etr ON etr.ENTRUST_ID = etr_add.ENTRUST_ID
etr.TRADE_MARKET = #{TRADE_PLACE_03}
AND etr.COUNTER_ID = #{counterId}
) t
t.COUNTER_ORG like concat('%',concat(#{param},'%'))

SELECT t.COUNTER_TRADER code FROM ( SELECT DISTINCT etr.COUNTER_TRADER FROM ETR_ENTRUST_ADD etr_add INNER JOIN ETR_ENTRUST etr ON etr.ENTRUST_ID = etr_add.ENTRUST_ID
etr.TRADE_MARKET = #{TRADE_PLACE_03}
AND etr_add.COUNTER_ORG = #{counterOrg}
) t
t.COUNTER_TRADER like concat('%',concat(#{param},'%'))

		select count(*) from FIN_CASH_INFO r
		inner join FIN_EXERCISE_PLAN q
		on r.cash_id = q.cash_id
		and q.exercise_type = #{EXEC_MODE_02}  
		where r.cash_type_2 = #{CASH_TYPE_2_C01}
		and r.branch = 0

			and r.finprod_id = #{finprodId}


            AND q.VDATE <=to_date(#{startDate},'yyyy-MM-dd')
            AND q.MDATE >=to_date(#{startDate},'yyyy-MM-dd')

		select t.scale from FIN_STDSEC_CONVERSE_RADIO t where t.branch = 0 and rownum = 1

			and t.finprod_id = #{finprodId}

		AND t.VDATE <= #{date}
        AND t.MDATE >= #{date}
        order by t.VDATE desc

select t.ACCT_NO from PTL_CAPACCT_INFO t left join STL_SEC_ACCT_INFO v on t.ACCT_NO = v.TRD_ACCT_ID
t.ACCT_TYPE = 'A07'
and t.PORTFOLIO_ID = #{portfolioId}
and v.TRADE_PLACE = #{tradeMarket}

select ssai.trade_place as tradeMarket, abs(nvl(SUM(t.amount),0)) as secNum from ETR_SEC_POSITION_FLOW t INNER JOIN STL_SEC_ACCT_INFO ssai on t.sec_acct_id = ssai.sec_acct_id and ssai.sec_acct_type = 'SEC' where t.finprod_id = 'XN_PRODID999' and t.hoding_type = 'E01' and t.branch = 0 and t.trade_id not in (SELECT ee.ENTRUST_ID FROM ETR_ENTRUST ee WHERE ee.PS IN ('T68', 'T69') UNION SELECT tsf.SEQNO FROM TRD_STASEC_FLOW tsf UNION SELECT tsf.SEQNO FROM TRD_TEMP_STASEC_FLOW tsf)
AND t.PORTFOLIO_ID = #{portfolioId}
AND ssai.trade_place = #{tradeMarket}
GROUP BY SSAI.TRADE_PLACE

SELECT CASE WHEN #{ps} = #{PS_03} THEN FLOOR(NVL(T.STNUM,0) * T.MORE_CONVRATE) - NVL(SECNUM,0) ELSE FLOOR((NVL(T.STNUM,0) * T.MORE_CONVRATE - NVL(SECNUM,0))/T.MORE_CONVRATE) END AS canUse FROM (SELECT T.PORTFOLIO_ID, T.TRD_ACCT_ID, T.TRADE_PLACE, T.STNUM, V.SECNUM, NVL(SBMCI.MORE_CONVRATE,SBMCICP.MORE_CONVRATE) AS MORE_CONVRATE FROM (SELECT TSF.PORTFOLIO_ID, SSAI.TRD_ACCT_ID, SSAI.TRADE_PLACE, FLOOR(SUM(CASE WHEN TSF.PS = #{PS_T68} THEN NVL(TSFD.AMT, 0) ELSE -1 * NVL(TSFD.AMT, 0) END * FSCR.SCALE)) STNUM FROM (SELECT PORTFOLIO_ID, SEC_ACCT_ID, PS, SEQNO FROM TRD_STASEC_FLOW WHERE CDATE <= to_date(#{sysDate},'yyyy-MM-dd')
) TSF
INNER JOIN (SELECT SEQNO, FINPROD_ID, BRANCH, AMT FROM TRD_STASEC_FLOW_DETAIL
) TSFD
ON TSFD.SEQNO = TSF.SEQNO LEFT JOIN STL_SEC_ACCT_INFO SSAI ON TSF.SEC_ACCT_ID = SSAI.SEC_ACCT_ID LEFT JOIN FIN_STDSEC_CONVERSE_RADIO FSCR ON TSFD.FINPROD_ID = FSCR.FINPROD_ID WHERE SSAI.SEC_ACCT_TYPE = 'SEC' AND FSCR.VDATE <= to_date(#{sysDate},'yyyy-MM-dd') AND FSCR.MDATE >= to_date(#{sysDate},'yyyy-MM-dd')
and TSF.PORTFOLIO_ID = #{portfolioId}
and SSAI.TRADE_PLACE = #{tradeMarket}
GROUP BY TSF.PORTFOLIO_ID, SSAI.TRD_ACCT_ID, SSAI.TRADE_PLACE) T LEFT JOIN (select T.PORTFOLIO_ID, SSAI.TRADE_PLACE, abs(nvl(SUM(t.amount), 0)) as secNum from ETR_SEC_POSITION_FLOW t INNER JOIN STL_SEC_ACCT_INFO ssai on t.sec_acct_id = ssai.sec_acct_id and ssai.sec_acct_type = 'SEC' where t.finprod_id = #{finprodId} and t.hoding_type = 'E01' and t.branch = 0 and t.trade_id not in (SELECT ee.ENTRUST_ID FROM ETR_ENTRUST ee WHERE ee.PS IN (#{PS_T68}, #{PS_T69}) UNION SELECT tsf.SEQNO FROM TRD_STASEC_FLOW tsf UNION SELECT tsf.SEQNO FROM TRD_TEMP_STASEC_FLOW tsf)
and T.PORTFOLIO_ID = #{portfolioId}
and SSAI.TRADE_PLACE = #{tradeMarket}
GROUP BY T.PORTFOLIO_ID, SSAI.TRADE_PLACE) V ON T.PORTFOLIO_ID = V.PORTFOLIO_ID AND T.TRADE_PLACE = V.TRADE_PLACE LEFT JOIN STD_BOND_MORE_CONVRATE_INFO SBMCI ON T.TRD_ACCT_ID = SBMCI.ACCT_NO LEFT JOIN STD_BOND_MORE_CONVRATE_INFO SBMCICP ON #{BROKER} = SBMCICP.ACCT_NO) T

